$(document).ready(function(){$("#domain-submit").click(function(){const t=$("#domain-value").val().replaceAll(/\s/g,""),n=t.split(";"),i=/^[a-z0-9]+([\-\.]{1}[a-z0-9]+)*\.[a-z]{2,6}$/;$("#invalidDomainMsg").hide();for(let t=0;t<n.length;t++)if(!i.test(n[t])&&n[t]!==""){const i=$("#domain-id");return i.length>0&&$("#domain-id").remove(),$("#invalidDomainMsg").append('<span id="domain-id">'+n[t]+"<\/span>").show(),!1}const r=$("#DomainId").val();$.ajax({type:"POST",url:"/domain/update",data:{id:r,value:t},success:function(){$("#successMsg").show();setTimeout(function(){$("#successMsg").hide()},1e3)}})})});